files.src/application_models.rs:
//! The application models the conversions use: a copy of the types DB2CRUD read.

/// Level, as the application has it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Level {
    Basic,
    Gold,
}

/// LineStatus, as the application has it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum LineStatus {
    Pending,
    Sent,
}

/// Location, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Location {
    pub latitude: f64,
    pub longitude: f64,
}

/// Address, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Address {
    pub street: String,
    pub zip_code: String,
    pub location: Option<Location>,
}

/// Customer, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Customer {
    pub id: String,
    pub email: String,
    pub level: Option<Level>,
    pub since: chrono::DateTime<chrono::Utc>,
    pub address: Address,
    pub tags: Vec<String>,
}

/// Discount, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Discount {
    pub reason: String,
    pub percent: f64,
}

/// OrderLine, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct OrderLine {
    pub id: Option<String>,
    pub sku: String,
    pub quantity: i32,
    pub price: rust_decimal::Decimal,
    pub status: Option<LineStatus>,
    pub discounts: Vec<Discount>,
}

/// Shipping, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Shipping {
    pub carrier: String,
    pub sent_on: chrono::NaiveDate,
}

/// Order, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Order {
    pub id: String,
    pub code: String,
    pub lines: Vec<OrderLine>,
    pub shipping: Option<Shipping>,
}

/// Parcel, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Parcel {
    pub weight: f64,
    pub size: String,
    pub fragile: bool,
}

/// Shipment, as the application has it.
#[derive(Debug, Clone, PartialEq)]
pub struct Shipment {
    pub id: String,
    pub parcel: Parcel,
    pub stops: Vec<String>,
}

