use crate::bson_values;
use crate::bson_values::Loaded;
use mongodb::bson::Document;
use mongodb::error::Error;

/// A document of the "customers" collection. A field stays `None` until it is set or read.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Customer {
    pub id: Option<String>,
    pub email: Option<String>,
    pub level: Option<String>,
    pub since: Option<chrono::DateTime<chrono::Utc>>,
    pub address: Option<CustomerAddress>,
    pub tags: Option<Vec<String>>,
    /// As it was read: a change writes only what differs
    pub loaded_document: Loaded,
}

impl Customer {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        let mut entity = Customer {
            id: bson_values::read(document, "_id", bson_values::as_object_id)?,
            email: bson_values::read(document, "email", bson_values::as_text)?,
            level: bson_values::read(document, "level", bson_values::as_text)?,
            since: bson_values::read(document, "since", bson_values::as_moment)?,
            address: bson_values::read(document, "address", bson_values::as_nested(CustomerAddress::from_document))?,
            tags: bson_values::read(document, "tags", bson_values::as_list(bson_values::as_text))?,
            loaded_document: Loaded::default(),
        };
        entity.loaded_document = Loaded(Some(entity.to_document()?));
        Ok(entity)
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "_id", &self.id, bson_values::of_object_id)?;
        bson_values::write(&mut document, "email", &self.email, bson_values::of_text)?;
        bson_values::write(&mut document, "level", &self.level, bson_values::of_text)?;
        bson_values::write(&mut document, "since", &self.since, bson_values::of_moment)?;
        bson_values::write(&mut document, "address", &self.address, bson_values::of_nested(CustomerAddress::to_document))?;
        bson_values::write(&mut document, "tags", &self.tags, bson_values::of_list(bson_values::of_text))?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CustomerAddress {
    pub street: Option<String>,
    pub zip_code: Option<String>,
    pub location: Option<CustomerAddressLocation>,
}

impl CustomerAddress {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        Ok(CustomerAddress {
            street: bson_values::read(document, "street", bson_values::as_text)?,
            zip_code: bson_values::read(document, "zip code", bson_values::as_text)?,
            location: bson_values::read(document, "location", bson_values::as_nested(CustomerAddressLocation::from_document))?,
        })
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "street", &self.street, bson_values::of_text)?;
        bson_values::write(&mut document, "zip code", &self.zip_code, bson_values::of_text)?;
        bson_values::write(&mut document, "location", &self.location, bson_values::of_nested(CustomerAddressLocation::to_document))?;
        Ok(document)
    }
}

/// A nested document: it is stored with the one that holds it.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct CustomerAddressLocation {
    pub latitude: Option<f64>,
    pub longitude: Option<f64>,
}

impl CustomerAddressLocation {
    /// What a document holds.
    pub fn from_document(document: &Document) -> Result<Self, Error> {
        Ok(CustomerAddressLocation {
            latitude: bson_values::read(document, "latitude", bson_values::as_f64)?,
            longitude: bson_values::read(document, "longitude", bson_values::as_f64)?,
        })
    }

    /// Its document: what is None is left out.
    pub fn to_document(&self) -> Result<Document, Error> {
        let mut document = Document::new();
        bson_values::write(&mut document, "latitude", &self.latitude, bson_values::of_f64)?;
        bson_values::write(&mut document, "longitude", &self.longitude, bson_values::of_f64)?;
        Ok(document)
    }
}

