//! The repositories of the "customers" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::bson_values;
use crate::bson_values::Loaded;
use crate::common::Page;
use crate::database::Db;
use crate::entities::customer::Customer;
use crate::errors::DomainError;
use mongodb::bson::doc;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where customers rows are kept. Services depend only on this trait.
#[async_trait]
pub trait CustomerRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Customer>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError>;

    /// The row with this email, or None.
    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Customer) -> Result<Customer, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Customer) -> Result<(), DomainError>;

    /// Adds an item to tags, and gives the row as it is then, if there is one.
    async fn add_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError>;

    /// Removes an item from tags, and gives the row as it is then, if there is one.
    async fn remove_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError>;
}

/// Keeps customers rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoCustomerRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoCustomerRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl CustomerRepository for MongoCustomerRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Customer>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("customers", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Customer::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError> {
        let total = self.db.count("customers", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("customers", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Customer::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError> {
        let found = self.db.find_one("customers", doc! { "email": bson_values::of_text(&email)? }).await?;
        Ok(found.as_ref().map(Customer::from_document).transpose()?)
    }

    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let document = entity.to_document()?;
        self.db.insert("Customer", "customers", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Customer) -> Result<Customer, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["email", "level", "since", "address", "tags"]);
        if !changes.is_empty() {
            self.db.update("Customer", "customers", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Customer) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Customer", "customers", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "tags": bson_values::of_text(&tag)? } };
        let changed = self.db.change("Customer", "customers", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Customer::from_document).transpose()?)
    }

    async fn remove_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$pull": { "tags": bson_values::of_text(&tag)? } };
        let changed = self.db.change("Customer", "customers", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Customer::from_document).transpose()?)
    }
}

/// Keeps customers rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryCustomerRepository {
    rows: Arc<Mutex<Vec<Customer>>>,
}

impl MemoryCustomerRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Customer> {
        let mut rows: Vec<Customer> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Customer) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Customer) -> (Option<String>,) {
    (row.id.clone(),)
}

#[async_trait]
impl CustomerRepository for MemoryCustomerRepository {
    async fn find_by_id(&self, id: String) -> Result<Option<Customer>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Customer>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn find_by_email(&self, email: String) -> Result<Option<Customer>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.email.as_ref() == Some(&email)))
    }

    async fn insert(&self, entity: Customer) -> Result<Customer, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Customer) -> Result<Customer, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Customer) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.tags.get_or_insert_default().push(tag);
        self.store(&found);
        Ok(Some(found))
    }

    async fn remove_tag(&self, id: String, tag: String) -> Result<Option<Customer>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.tags.get_or_insert_default().retain(|item| *item != tag);
        self.store(&found);
        Ok(Some(found))
    }
}

