        self.db.delete("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<Option<Order>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let mut line = line;
        line.id = line.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let change = doc! { "$push": { "lines": bson_values::of_nested(crate::entities::order::OrderLine::to_document)(&line)? } };
        let changed = self.db.change("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Order::from_document).transpose()?)
    }

    async fn remove_line(&self, id: String, line_id: String) -> Result<Option<Order>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        if !bson_values::is_object_id(&line_id) {
            return Ok(None);
        }
        let change = doc! { "$pull": { "lines": { "_id": bson_values::of_object_id(&line_id)? } } };
        let changed = self.db.change("Order", "orders", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Order::from_document).transpose()?)
    }
}

/// Keeps orders rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryOrderRepository {
    rows: Arc<Mutex<Vec<Order>>>,
}

impl MemoryOrderRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Order> {
        let mut rows: Vec<Order> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Order) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
