        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        entity.identify_items();
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Order) -> Result<Order, DomainError> {
        let mut entity = entity;
        entity.identify_items();
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Order) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }

    async fn add_line(&self, id: String, line: crate::entities::order::OrderLine) -> Result<Option<Order>, DomainError> {
        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        let mut line = line;
        line.id = line.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
