        let Some(mut found) = self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)) else {
            return Ok(None);
        };
        found.lines.get_or_insert_default().retain(|item| item.id.as_ref() != Some(&line_id));
        self.store(&found);
        Ok(Some(found))
    }
}

