/// Where shipments rows are kept. Services depend only on this trait.
#[async_trait]
pub trait ShipmentRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_id(&self, id: String) -> Result<Option<Shipment>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Shipment>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Shipment) -> Result<Shipment, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Shipment) -> Result<Shipment, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Shipment) -> Result<(), DomainError>;

    /// Adds an item to stops, and gives the row as it is then, if there is one.
    async fn add_stop(&self, id: String, stop: crate::entities::shipment::ShipmentStop) -> Result<Option<Shipment>, DomainError>;

    /// Removes an item from stops that has this size, and gives the row as it is then, if there is one.
    async fn remove_stop(&self, id: String, position: usize, size: usize) -> Result<Option<Shipment>, DomainError>;
}

/// Keeps shipments rows in the database, through the MongoDB driver: on the connection of the unit of work, or in its transaction.
pub struct MongoShipmentRepository<'a> {
    db: &'a Db,
}

impl<'a> MongoShipmentRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl ShipmentRepository for MongoShipmentRepository<'_> {
    async fn find_by_id(&self, id: String) -> Result<Option<Shipment>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let found = self.db.find_one("shipments", doc! { "_id": bson_values::of_object_id(&id)? }).await?;
        Ok(found.as_ref().map(Shipment::from_document).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Shipment>, DomainError> {
        let total = self.db.count("shipments", doc! {}).await?;
        let found = if limit > 0 {
            self.db.find("shipments", doc! {}, doc! { "_id": 1 }, offset, limit).await?
        } else {
            Vec::new()
        };
        Ok(Page { items: found.iter().map(Shipment::from_document).collect::<Result<_, _>>()?, total, offset, limit })
    }

    async fn insert(&self, entity: Shipment) -> Result<Shipment, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| Some(mongodb::bson::oid::ObjectId::new().to_hex()));
        let document = entity.to_document()?;
        self.db.insert("Shipment", "shipments", &document).await?;
        entity.loaded_document = Loaded(Some(document));
        Ok(entity)
    }

    async fn update(&self, entity: Shipment) -> Result<Shipment, DomainError> {
        let mut entity = entity;
        let now = entity.to_document()?;
        let changes = bson_values::changes(entity.loaded_document.0.as_ref(), &now, &["parcel", "stops"]);
        if !changes.is_empty() {
            self.db.update("Shipment", "shipments", doc! { "_id": now.get("_id").cloned() }, changes).await?;
        }
        entity.loaded_document = Loaded(Some(now));
        Ok(entity)
    }

    async fn delete(&self, entity: &Shipment) -> Result<(), DomainError> {
        let id = entity.id.clone().expect("id is set");
        self.db.delete("Shipment", "shipments", doc! { "_id": bson_values::of_object_id(&id)? }).await
    }

    async fn add_stop(&self, id: String, stop: crate::entities::shipment::ShipmentStop) -> Result<Option<Shipment>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let change = doc! { "$push": { "stops": bson_values::of_nested(crate::entities::shipment::ShipmentStop::to_document)(&stop)? } };
        let changed = self.db.change("Shipment", "shipments", doc! { "_id": bson_values::of_object_id(&id)? }, change).await?;
        Ok(changed.as_ref().map(Shipment::from_document).transpose()?)
    }

    async fn remove_stop(&self, id: String, position: usize, size: usize) -> Result<Option<Shipment>, DomainError> {
        if !bson_values::is_object_id(&id) {
            return Ok(None);
        }
        let head = doc! { "$slice": ["$stops", position as i64] };
        let tail = doc! { "$slice": ["$stops", position as i64 + 1, size.max(1) as i64] };
        let change = vec![doc! { "$set": { "stops": { "$concatArrays": [head, tail] } } }];
        let changed = self.db.change("Shipment", "shipments", doc! { "_id": bson_values::of_object_id(&id)?, "stops": { "$size": size as i64 } }, change).await?;
        Ok(changed.as_ref().map(Shipment::from_document).transpose()?)
    }
}

