//! The service of the "shipments" table.

use crate::common::Page;
use crate::entities::shipment::Shipment;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Shipment that change: fields left Absent keep their value; Patch::Set(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ShipmentChanges {
    pub parcel: crate::common::Patch<Option<crate::entities::shipment::ShipmentParcel>>,
    pub stops: crate::common::Patch<Option<Vec<crate::entities::shipment::ShipmentStop>>>,
}

/// Operations on shipments. Repositories commit every write.
pub struct ShipmentService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl ShipmentService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Shipment after checking it.
    pub async fn create_shipment(&self, shipment: Shipment) -> Result<Shipment, DomainError> {
        let values = Values { parcel: shipment.parcel.map(Some), stops: shipment.stops.map(Some) };
        let uow = self.unit_of_work.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Shipment::default();
        apply_values(&mut entity, &values);
        let created = uow.shipments().insert(entity).await?;
        Ok(created)
    }

    /// The Shipment with this key; NotFound when there is none.
    pub async fn get_shipment(&self, id: String) -> Result<Shipment, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of shipments, by primary key.
    pub async fn list_shipments(&self, offset: u64, limit: u64) -> Result<Page<Shipment>, DomainError> {
        self.unit_of_work.shipments().list(offset, limit).await
    }

    /// Changes the given values of a Shipment.
    pub async fn update_shipment(&self, id: String, changes: ShipmentChanges) -> Result<Shipment, DomainError> {
        let values = given(changes);
        let uow = self.unit_of_work.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.shipments().update(current).await?;
        Ok(updated)
    }

    /// Deletes a Shipment.
    pub async fn delete_shipment(&self, id: String) -> Result<(), DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id).await?;
        uow.shipments().delete(&current).await?;
        Ok(())
    }

    /// Adds an item to stops.
    pub async fn add_stop(&self, id: String, stop: crate::entities::shipment::ShipmentStop) -> Result<Shipment, DomainError> {
        let mut errors: Vec<FieldError> = Vec::new();
        check_shipment_stop(&stop, "stops", &mut errors);
        if !errors.is_empty() {
            return Err(DomainError::ValidationFailed { entity: "Shipment".to_string(), errors });
        }
        let uow = self.unit_of_work.as_ref();
        find(uow, id.clone()).await?;
        let changed = uow.shipments().add_stop(id.clone(), stop).await?.ok_or_else(|| DomainError::not_found("Shipment", id))?;
        Ok(changed)
    }

    /// Removes an item from stops, by its position.
    pub async fn remove_stop(&self, id: String, position: usize) -> Result<Shipment, DomainError> {
        let uow = self.unit_of_work.as_ref();
        let current = find(uow, id.clone()).await?;
        if !(position < current.stops.as_deref().unwrap_or_default().len()) {
            return Err(DomainError::not_found("Stop", position));
        }
        let size = current.stops.as_deref().unwrap_or_default().len();
        let changed = uow.shipments().remove_stop(id.clone(), position, size).await?.ok_or_else(|| DomainError::conflict("Shipment", "was changed by someone else since it was read", &["stops"]))?;
        Ok(changed)
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    parcel: Option<Option<crate::entities::shipment::ShipmentParcel>>,
    stops: Option<Option<Vec<crate::entities::shipment::ShipmentStop>>>,
}

/// Checks the values against the rules of the "shipments" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(_uow: &dyn UnitOfWork, values: &Values, current: Option<&Shipment>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.parcel.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.parcel.is_some() {
                errors.push(FieldError::new("parcel", "is required"));
            }
        }
        Some(value) => {
            check_shipment_parcel(value, "parcel", &mut errors);
        }
    }
    if let Some(value) = values.stops.as_ref().and_then(|value| value.as_ref()) {
        for (i0, item0) in value.iter().enumerate() {
            check_shipment_stop(item0, &format!("stops.{i0}"), &mut errors);
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Shipment".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Shipment>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Shipment, values: &Values) {
    if let Some(value) = &values.parcel {
        entity.parcel = value.clone();
    }
    if let Some(value) = &values.stops {
        entity.stops = value.clone();
    }
}

/// What a ShipmentParcel does not follow of its rules, each with the path of its field.
fn check_shipment_parcel(value: &crate::entities::shipment::ShipmentParcel, path: &str, errors: &mut Vec<FieldError>) {
    if value.weight.is_none() {
        errors.push(FieldError::new(&format!("{path}.weight"), "is required"));
    }
    if value.contents.is_none() {
        errors.push(FieldError::new(&format!("{path}.contents"), "is required"));
    }
    if let Some(held) = &value.size {
        check_shipment_parcel_size(held, &format!("{path}.size"), errors);
    }
}

/// What a ShipmentParcelSize does not follow of its rules, each with the path of its field.
fn check_shipment_parcel_size(value: &crate::entities::shipment::ShipmentParcelSize, path: &str, errors: &mut Vec<FieldError>) {
    if value.height.is_none() {
        errors.push(FieldError::new(&format!("{path}.height"), "is required"));
    }
}

/// What a ShipmentStop does not follow of its rules, each with the path of its field.
fn check_shipment_stop(_value: &crate::entities::shipment::ShipmentStop, _path: &str, _errors: &mut Vec<FieldError>) {
}

/// The values an update gives, by field.
fn given(changes: ShipmentChanges) -> Values {
    Values { parcel: changes.parcel.given(), stops: changes.stops.given() }
}

/// The Shipment with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: String) -> Result<Shipment, DomainError> {
    uow.shipments().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Shipment", id))
}

