//! The service of the "customers" table, on the in-memory repositories.

use mongorust_mongodb_conversions::common::Patch;
use mongorust_mongodb_conversions::errors::DomainError;
use mongorust_mongodb_conversions::services::customer::{CustomerChanges, CustomerService};
use mongorust_mongodb_conversions::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    let row = factories::new_customer(1);
    let created = service.create_customer(row).await.expect("a create");
    let found = service.get_customer(created.id.clone().expect("id is set")).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    let mut row = factories::new_customer(1);
    row.email = None;
    let error = service.create_customer(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["email"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn refuses_a_repeated_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    let row = factories::new_customer(1);
    let first = service.create_customer(row).await.expect("a create");
    let mut again = factories::new_customer(2);
    again.email = first.email.clone();
    assert!(matches!(service.create_customer(again).await, Err(DomainError::Conflict { .. })));
}

#[tokio::test]
async fn keeps_its_own_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    let row = factories::new_customer(1);
    let created = service.create_customer(row.clone()).await.expect("a create");
    let updated = service.update_customer(created.id.clone().expect("id is set"), CustomerChanges { email: Patch::Set(created.email.clone()), ..Default::default() }).await.expect("an update");
    assert_eq!(created.email, updated.email);
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    assert!(matches!(service.get_customer("ffffffffffffffffffffffff".to_string()).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = CustomerService::new(uow.clone());
    let row = factories::new_customer(1);
    let created = service.create_customer(row).await.expect("a create");
    service.delete_customer(created.id.clone().expect("id is set")).await.expect("a delete");
    assert!(matches!(service.get_customer(created.id.clone().expect("id is set")).await, Err(DomainError::NotFound { .. })));
